sp_widget.client_script:
function widgetcontroller($scope, $rootScope) {
    var c = this;
    c.loading = false;

    // Formatter used in HTML
    c.formatLakh = function(v) {
        if (v === undefined || v === null || v === '') return '';
        var n = parseFloat(v);
        if (isNaN(n)) return v;
        var abs = Math.abs(n);
        var sign = n < 0 ? '-' : '';
        return sign + '\u20B9' + (abs / 100000).toFixed(1) + 'L';
    };

    // ========================================================
    // BADGE COLOR MAPPINGS
    // ========================================================
    c.getStatusBadgeClass = function(status) {
        var s = (status || '').toLowerCase();
        if (s.indexOf('submit') > -1 || s.indexOf('pend') > -1) return 'badge-yellow';
        if (s.indexOf('approv') > -1) return 'badge-green';
        if (s.indexOf('reject') > -1) return 'badge-red';
        if (s.indexOf('return') > -1 || s.indexOf('send') > -1) return 'badge-purple';
        return 'badge-default';
    };

    c.getRiskBadgeClass = function(risk) {
        var r = (risk || '').toLowerCase();
        if (r === 'low') return 'badge-green';
        if (r === 'medium') return 'badge-amber';
        if (r === 'high') return 'badge-red';
        return 'badge-default';
    };

    // Centralized function to fetch data from server
    function loadRequestDetails(reqNumber) {
        if (!reqNumber) return;
        c.loading = true;
        c.server.get({ action: 'load_request', number: reqNumber }).then(function(r) {
            c.data.record = r.data.record;
            c.data.error = r.data.error;
            c.loading = false;
        });
    }

    // 1. Listen for the drill-down click event from the Approval Requests table
    $rootScope.$on('clm.request.selected', function(event, payload) {
        if (payload && payload.number) {
            loadRequestDetails(payload.number);
        }
    });

    // 2. Failsafe: Check if a request was already clicked right before this tab loaded
    if ($rootScope.clmPendingRequestNumber) {
        loadRequestDetails($rootScope.clmPendingRequestNumber);
    }
}

sp_widget.css:
/* ===================== BASE PORTAL & TYPOGRAPHY ===================== */
.clm-detail-portal {
    font-family: "Helvetica Neue", Arial, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
    color: #1a1a1a;
    width: 100%; /* FIX: Forces full width like other tabs */
    padding: 8px;
    font-size: 12.5px;
}

/* ===================== RIBBON ===================== */
.clm-ribbon {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    background: #ffffff;
    border: 1px solid #cbd5e1;
    border-radius: 4px;
    padding: 8px 14px;
    margin-bottom: 8px;
}

.clm-label {
    font-size: 9.5px;
    font-weight: 600;
    letter-spacing: 0.05em;
    color: #9ca3af;
    text-transform: uppercase;
}

.clm-number {
    font-size: 17px;
    font-weight: 700;
    color: #1a1a1a;
    margin-top: 1px;
    line-height: 1.2;
}

.clm-subline {
    font-size: 11.5px;
    color: #6b7280;
    margin-top: 2px;
}

.clm-subline .clm-dot {
    margin: 0 6px;
    color: #d1d5db;
}

.clm-ribbon-right {
    display: flex;
    align-items: center;
    gap: 6px;
    flex-wrap: wrap;
    justify-content: flex-end;
}

.clm-badge {
    font-size: 10.5px;
    font-weight: 600;
    padding: 2px 7px;
    border-radius: 3px;
    white-space: nowrap;
}

.clm-badge-red {
    background: #fde3e3;
    color: #b3261e;
}

/* ===================== LIMIT BANNER ===================== */
.clm-limit-banner {
    background: #eef4fe;
    border: 1px solid #e0eafc;
    border-radius: 8px;
    padding: 20px 32px;
    margin-bottom: 8px;
}

.clm-limit-inner {
    display: flex;
    align-items: center;
    justify-content: space-between;
    max-width: 620px;
    margin: 0 auto;
}

.clm-limit-block {
    text-align: left;
}

.clm-limit-block-right {
    text-align: right;
}

.clm-limit-label {
    font-size: 12px;
    font-weight: 600;
    letter-spacing: 0.03em;
    color: #64748b;
    text-transform: uppercase;
}

.clm-limit-pct {
    color: #1c4e9c;
    font-weight: 700;
    font-size: 12px;
    margin-left: 4px;
    text-transform: none;
    letter-spacing: normal;
}

.clm-pct-neg {
    color: #b3261e;
}

.clm-limit-value {
    font-size: 28px;
    font-weight: 700;
    color: #334155;
    margin-top: 4px;
    line-height: 1.2;
}

.clm-limit-value-blue {
    color: #1c4e9c;
}

.clm-limit-arrow {
    font-size: 18px;
    color: #7c93b8;
    padding: 0 12px;
}

/* ===================== COLUMN LAYOUT ===================== */
.clm-columns {
    display: flex;
    gap: 8px;
    align-items: flex-start;
}

.clm-col-left {
    flex: 1 1 58%;
    display: flex;
    flex-direction: column;
    gap: 8px;
    min-width: 0;
}

.clm-col-right {
    flex: 1 1 42%;
    display: flex;
    flex-direction: column;
    gap: 8px;
    min-width: 0;
}

@media (max-width: 860px) {
    .clm-columns {
        flex-direction: column;
    }
}

/* ===================== CARDS & DATA ROWS ===================== */
.clm-card {
    background: #ffffff;
    border: 1px solid #cbd5e1;
    border-radius: 4px;
    padding: 10px 14px;
    margin-bottom: 16px;
    box-shadow: 0 1px 2px rgba(0,0,0,0.03);
}

.clm-card-title {
    font-size: 12.5px;
    font-weight: 700;
    color: #1a1a1a;
    margin-bottom: 2px;
}

.clm-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 6px 0;
    border-bottom: 1px solid #f1f2f4;
    font-size: 12px;
}

.clm-row-last {
    border-bottom: none;
}

.clm-row-label {
    color: #6b7280;
}

.clm-row-value {
    font-weight: 600;
    color: #1a1a1a;
}

.clm-text-blue {
    color: #1c4e9c;
}

.clm-text-red {
    color: #b3261e;
}

.clm-pill {
    font-size: 10.5px;
    font-weight: 600;
    padding: 2px 7px;
    border-radius: 3px;
}

.clm-pill-green {
    background: #dbf5e3;
    color: #1f9d55;
}

.clm-pill-red {
    background: #fde3e3;
    color: #b3261e;
}

.clm-justification-box {
    border-left: 2px solid #1c4e9c;
    background: #f8f9fb;
    padding: 7px 11px;
    font-size: 12px;
    color: #374151;
    border-radius: 0 3px 3px 0;
    /* FIX: Prevents long text from bleeding out of the container */
    word-wrap: break-word;        
    overflow-wrap: break-word;    
    white-space: pre-wrap;        
}

/* ===================== WORKFLOW TRAIL ===================== */
.clm-workflow {
    position: relative;
    padding-left: 2px;
}

.clm-workflow-step {
    display: flex;
    gap: 9px;
    position: relative;
    padding-bottom: 12px;
}

.clm-workflow-step:not(:last-child)::before {
    content: "";
    position: absolute;
    left: 3px;
    top: 13px;
    bottom: 0;
    width: 1px;
    background: #e5e7eb;
}

.clm-workflow-dot {
    flex: 0 0 auto;
    width: 7px;
    height: 7px;
    border-radius: 50%;
    margin-top: 4px;
    background: #1c4e9c;
}

.clm-workflow-dot.clm-dot-rejected {
    background: #b3261e;
}

.clm-workflow-dot.clm-dot-approved {
    background: #1f9d55;
}

.clm-workflow-content {
    flex: 1 1 auto;
    min-width: 0;
}

.clm-workflow-header {
    font-size: 12px;
    font-weight: 700;
    color: #1a1a1a;
}

.clm-workflow-role {
    color: #1a1a1a;
}

.clm-workflow-meta {
    font-size: 10.5px;
    color: #9ca3af;
    margin-top: 1px;
}

.clm-workflow-comment {
    margin-top: 6px;
    background: #fde3e3;
    color: #7f1d1d;
    font-size: 11.5px;
    font-style: normal;
    border-left: 2px solid #b3261e;
    padding: 5px 9px;
    border-radius: 0 3px 3px 0;
}

.clm-workflow-banner {
    margin-top: 4px;
    background: #fde3e3;
    color: #b3261e;
    font-weight: 700;
    font-size: 11.5px;
    text-align: center;
    letter-spacing: 0.03em;
    padding: 7px;
    border-radius: 3px;
}

/* ===================== EMPTY STATE ===================== */
.clm-empty {
    text-align: center;
    color: #6b7280;
    padding: 60px 20px;
    font-size: 13.5px;
    background: #fff;
    border: 1px solid #cbd5e1;
    border-radius: 8px;
    margin-top: 20px;
}
/* Custom Badge Formatting */
.custom-badge {
    display: inline-block;
    padding: 4px 10px;
    border-radius: 4px;
    font-size: 11px;
    font-weight: 600;
    white-space: nowrap;
}

/* Color Assignments */
.badge-yellow { background-color: #fffdf0 !important; color: #975a16 !important; }
.badge-amber  { background-color: #fff3e0 !important; color: #d97b0d !important; }
.badge-green  { background-color: #e3f4ea !important; color: #1f7a4d !important; }
.badge-red    { background-color: #fdeaea !important; color: #e53e3e !important; }
.badge-purple { background-color: #f0e6ff !important; color: #6b21a8 !important; }
.badge-default{ background-color: #f8f9fa !important; color: #4a5568 !important; }

sp_widget.script:
(function() {
    data.record = null;
    data.error = '';

    // Only run server logic when specifically asked by the drill-down Client Script
    if (!input || input.action !== 'load_request' || !input.number) {
        return; 
    }

    var currentUserId = gs.getUserID();
    var userZone = '';
    var isZHM = false;

    // 1. Establish ZHM Security via Custom Mapping Table
    var grRole = new GlideRecord('x_birl3_clm_role_user_mapping');
    grRole.addQuery('u_user', currentUserId);
    grRole.addQuery('u_role', 'ZHM'); 
    grRole.query();
    if (grRole.next()) {
        isZHM = true;
        userZone = grRole.getValue('u_zone') || '';
    }

    // =========================================================
    // LIVE SAP CREDIT API HELPER (same as other widgets)
    // =========================================================
    function getLiveCreditData(customerCode, salesOrg) {
        var out = {
            creditLimit: 0,
            outstandingAmount: 0,
            availableCredit: 0,
            asdAmount: 0,
            state: '',
            raw: null,
            success: false
        };

        if (!customerCode) {
            gs.error('[RHM Request Details] getLiveCreditData called with no customer code.');
            return out;
        }

        try {
            var apiCall = new x_birl3_clm.CLM_NEW_WSDL1();
            var rawResult = apiCall.getCreditDetails(customerCode, salesOrg || '');

            if (!rawResult) {
                gs.error('[RHM Request Details] CLM_NEW_WSDL1 returned empty for ' + customerCode + '/' + salesOrg);
                return out;
            }

            var parsed = JSON.parse(rawResult);

            out.creditLimit       = parseFloat(parsed.creditLimit) || 0;
            out.outstandingAmount = parseFloat(parsed.outstandingAmount) || 0;
            out.availableCredit   = parseFloat(parsed.availableCredit) || 0;
            out.asdAmount         = parseFloat(parsed.ASDAmount) || 0;
            out.state             = parsed.state || '';
            out.raw = parsed;

            var allBlank = true;
            for (var k in parsed) {
                if (parsed[k]) { allBlank = false; break; }
            }
            if (allBlank) {
                gs.error('[RHM Request Details] CLM_NEW_WSDL1 returned blank data for ' + customerCode + '/' + salesOrg);
            } else {
                out.success = true;
            }

        } catch (e) {
            gs.error('[RHM Request Details] CLM_NEW_WSDL1 call threw exception for ' + customerCode + '/' + salesOrg + ': ' + e.message);
        }

        return out;
    }

    // 2. Fetch the specific Request using the Number passed from the UI
    var grReq = new GlideRecord('x_birl3_clm_clm_new_credit_request');
    grReq.addQuery('number', input.number);

    // Apply strict ZHM zone security
    if (isZHM && userZone) {
        grReq.addQuery('customer.zone', userZone);
    }

    grReq.setLimit(1);
    grReq.query();

    if (grReq.next()) {
        data.record = buildRecordPayload(grReq);
    } else {
        data.error = 'Request not found or you do not have permission to view it.';
    }

    // 3. Helper to format data and query related Master tables
    function buildRecordPayload(gr) {
        var reqSysId = gr.getUniqueValue();
        var reqCurrentLimit = parseFloat(gr.getValue('current_credit_limit')) || 0;
        var requestedLimit = parseFloat(gr.getValue('requested_limit')) || 0;
        var reqOutstanding = parseFloat(gr.getValue('outstanding_amount')) || 0;
        var activeSd = parseFloat(gr.getValue('active_sd')) || 0;
        var approvedLimit = parseFloat(gr.getValue('approved_limit')) || 0;

        var customerId = gr.getValue('customer');
        var customerCode = '';
        var customerSalesOrg = '';
        var customerName = '';
        var customerPan = '';
        var commodity = gr.getDisplayValue('segment');
        var riskClassification = 'Low';
        var accountStatusStr = gr.getDisplayValue('state') || 'Unknown';
        var overdue90 = 0;               // <-- DECLARATION ADDED HERE

        if (customerId) {
            var grMaster = new GlideRecord('x_birl3_clm_clm_customer_master1');
            if (grMaster.get(customerId)) {
                customerName = grMaster.getValue('customer_name') || '';
                customerPan  = grMaster.getValue('pan') || '';
                customerCode = grMaster.getValue('customer_code_sap') || '';
                customerSalesOrg = grMaster.getValue('salesorg') || '';
                if (!commodity) commodity = grMaster.getDisplayValue('segment');
            }

            // Existing overdue90 fetch
            var grOut = new GlideRecord('x_birl3_clm_clm_aging_snapshot');
            if (grOut.get('customer', customerId)) {
                overdue90 = parseFloat(grOut.getValue('ageing_gt90')) || 0;
            }

            // Risk Classification from Aging Snapshot
            var agingGr = new GlideRecord('x_birl3_clm_clm_aging_snapshot');
            agingGr.addQuery('customer', customerId);
            agingGr.query();
            if (agingGr.next()) {
                var over90Sum = (parseFloat(agingGr.getValue('bucket_91_120_days')) || 0) +
                                (parseFloat(agingGr.getValue('bucket_121_180_days')) || 0) +
                                (parseFloat(agingGr.getValue('bucket_181_365_days')) || 0) +
                                (parseFloat(agingGr.getValue('bucket_366_730_days')) || 0) +
                                (parseFloat(agingGr.getValue('bucket_730_above')) || 0) +
                                (parseFloat(agingGr.getValue('bucket_gt120_days')) || 0);

                var over60to90Sum = (parseFloat(agingGr.getValue('bucket_61_75_days')) || 0) +
                                    (parseFloat(agingGr.getValue('bucket_76_90_days')) || 0);

                if (over90Sum > 0) riskClassification = 'High';
                else if (over60to90Sum > 0) riskClassification = 'Medium';
            }
        }

        // --- LIVE API CALL ---
        var live = getLiveCreditData(customerCode, customerSalesOrg);
        var currentLimit = live.success ? live.creditLimit : reqCurrentLimit;
        var outstanding = live.success ? live.outstandingAmount : reqOutstanding;

        // --- Calculations based on chosen values ---
        var increaseAmount = requestedLimit - currentLimit;
        var increasePct = (currentLimit !== 0) ? Math.round((increaseAmount / currentLimit) * 100) : 0;
        var utilisationPctStr = (currentLimit > 0) ? ((outstanding / currentLimit) * 100).toFixed(1) + '%' : 'N/A';

        // Date & Days Left Calculation
        var reviewDateStr = gr.getValue('next_review_date');
        var reviewIn = 'No date set';
        if (reviewDateStr) {
            var reviewDate = new GlideDateTime(reviewDateStr);
            var today = new GlideDateTime();
            var daysDiff = GlideDateTime.subtract(today, reviewDate).getRoundedDayPart();

            if (daysDiff > 0) reviewIn = reviewDateStr + ' / ' + daysDiff + ' days left';
            else if (daysDiff === 0) reviewIn = reviewDateStr + ' / Due today';
            else reviewIn = reviewDateStr + ' / ' + Math.abs(daysDiff) + ' days overdue';
        }

        // ============================================================
        // DYNAMIC APPROVAL WORKFLOW TRAIL & PENDING STAGE
        // ============================================================
        var workflowTrail = [];
        var finalDecision = '';
        var activePendingApprovers = [];

        workflowTrail.push({
            role: 'Initiator',
            actor: gr.getDisplayValue('sys_created_by'),
            action: 'Submitted',
            date: gr.getDisplayValue('sys_created_on'),
            duration: '',
            comment: '',
            dotClass: 'clm-dot-approved'
        });

        var grApp = new GlideRecord('sysapproval_approver');
        var qc = grApp.addQuery('sysapproval', reqSysId);
        qc.addOrCondition('document_id', reqSysId);
        grApp.orderBy('sys_created_on'); 
        grApp.query();

        while (grApp.next()) {
            var appState = (grApp.getValue('state') || '').toLowerCase();
            var actionLabel = 'Pending';
            var dotClass = '';
            var actionDate = grApp.getDisplayValue('sys_created_on');
            var approverName = grApp.getDisplayValue('approver');

            if (appState === 'approved') {
                actionLabel = 'Approved';
                dotClass = 'clm-dot-approved';
                actionDate = grApp.getDisplayValue('sys_updated_on');
            } else if (appState === 'rejected') {
                actionLabel = 'Rejected';
                dotClass = 'clm-dot-rejected';
                actionDate = grApp.getDisplayValue('sys_updated_on');
                finalDecision = 'Request Rejected by ' + approverName;
            } else if (appState === 'requested') {
                actionLabel = 'Pending Approval';
                activePendingApprovers.push(approverName);
            } else if (appState === 'not_required' || appState === 'cancelled') {
                actionLabel = 'Skipped / Cancelled';
                actionDate = grApp.getDisplayValue('sys_updated_on');
            }

            workflowTrail.push({
                role: 'Approver',
                actor: approverName,
                action: actionLabel,
                date: actionDate,
                duration: '',
                comment: '', 
                dotClass: dotClass
            });
        }

        var reqState = (gr.getValue('state') || '').toLowerCase();
        var calculatedPendingStage = '';

        if (reqState.indexOf('approv') > -1) {
            finalDecision = 'Request Fully Approved';
            calculatedPendingStage = 'Approved';
        } else if (reqState.indexOf('reject') > -1) {
            calculatedPendingStage = 'Rejected';
        } else if (activePendingApprovers.length > 0) {
            calculatedPendingStage = 'Pending at ' + activePendingApprovers.join(', ');
        } else {
            calculatedPendingStage = accountStatusStr;
        }

        // Approved amount: show approved_limit only when state contains 'approv', else 'Pending'
        var approvedAmount = (reqState.indexOf('approv') > -1) ? approvedLimit : 'Pending';

        return {
            number: gr.getValue('number'),
            customerName: customerName,
            customerPan: customerPan,
            customerCode: customerCode,
            commodity: commodity,

            previousLimit: currentLimit,        // live credit limit (or fallback)
            requestedLimit: requestedLimit,
            increaseAmount: increaseAmount,
            increasePct: increasePct,

            pendingStage: calculatedPendingStage,
            tshJustification: gr.getValue('business_justification'),

            approvedAmount: approvedAmount,     // 'Pending' or actual approved limit
            securityDeposit: activeSd,
            utilisationPct: utilisationPctStr,

            accountStatus: accountStatusStr,
            riskClassification: riskClassification,

            outstandingAmount: outstanding,     // live outstanding (or fallback)
            overdue90: overdue90,
            reviewIn: reviewIn,

            statusBadge1: '',
            statusBadge2: '',

            workflowTrail: workflowTrail,
            finalDecisionLabel: finalDecision
        };
    }
})();
